'use client'

import type { ComponentProps, ReactNode } from 'react'
import { Button as UiButton } from '@ui-sdk/react/button'

import './button.css'

export type ButtonVariant =
  | 'neutral'
  | 'danger'
  | 'warning'
  | 'outline'
  | 'contrast'
  | 'submit'
  | 'ghost'
  | 'ghost-muted'
  | 'ghost-faint'
  | 'ghost-danger'
  | 'loading'
  | 'nav'

export type ButtonSize = 'small' | 'normal' | 'large'

type UiButtonProps = ComponentProps<typeof UiButton>

export type ButtonProps = Omit<UiButtonProps, 'render' | 'children'> & {
  /** Defaults to `neutral`, like opencode's button. */
  variant?: ButtonVariant
  /** Defaults to `normal` (28px). Ignored by `nav`, which is always 28px. */
  size?: ButtonSize
  /** Optional icon rendered before the label, at the button's 16px icon slot. */
  icon?: ReactNode
  /** Marks a `nav` item as the current page. */
  active?: boolean
  /** Renders an anchor instead of a button. */
  href?: string
  target?: string
  rel?: string
  download?: boolean | string
  children?: ReactNode
}

export function Button({
  variant = 'neutral',
  size = 'normal',
  icon,
  active,
  href,
  target,
  rel,
  download,
  children,
  ...rest
}: ButtonProps) {
  return (
    <UiButton
      {...rest}
      data-variant={variant}
      data-size={variant === 'nav' ? undefined : size}
      data-icon={icon ? '' : undefined}
      data-active={active ? '' : undefined}
      render={
        href
          ? (anchorProps) => (
              <a
                {...anchorProps}
                href={href}
                target={target}
                rel={rel}
                download={download}
              />
            )
          : undefined
      }
    >
      {icon}
      {children}
    </UiButton>
  )
}

/*
 * 1:1 port of opencode's Button (`@opencode/ui/button`, MIT):
 * packages/ui/src/actions/button/button.css + actions/submit.css.
 *
 * Only the selectors changed, to meet ui-sdk's markup. Every value is
 * upstream, so hover / pressed / focus / expanded / disabled / loading all
 * match `data-component="button-v2"`:
 *
 *   [data-component="button-v2"]  →  [data-slot="button"]  (ui-sdk's root slot)
 *   [data-state="disabled"]       →  also [data-disabled]  (ui-sdk's attribute)
 *   [data-slot="icon-svg"]        →  also a plain `svg`
 *
 * The rule set is attribute driven, so the React, Vue and web-component
 * bindings can reuse this file unchanged.
 *
 * `nav` is the one Kitsaas-only variant: it is the settings-sidebar link from
 * opencode's app, which lives outside button-v2.
 */

@layer components {
  [data-slot="button"] {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    border-radius: 6px;
    font-style: normal;
    font-weight: 530;
    font-size: 13px;
    line-height: 20px;
    color: var(--v2-text-text-base);
    text-shadow: none;
    font-variant-numeric: tabular-nums;
    letter-spacing: -0.04px;
    user-select: none;
    cursor: pointer;
    outline: none;
  }

  [data-slot="button"] > * {
    pointer-events: none;
  }

  [data-slot="button"]:focus {
    outline: none;
  }

  [data-slot="button"]:is(:focus-visible, [data-state="focus"]):not(:disabled):not([data-variant="loading"]) {
    outline: 2px solid var(--v2-border-border-focus);
    outline-offset: 2.5px;
  }

  [data-slot="button"][data-size="normal"] {
    height: 28px;
    padding: 0 11px;
  }

  [data-slot="button"][data-size="small"] {
    height: 24px;
    padding: 0 9px;
    border-radius: 4px;
  }

  [data-slot="button"][data-size="large"] {
    height: 32px;
    padding: 0 15px;
  }

  [data-slot="button"][data-icon][data-size="small"] {
    padding-left: 9px;
  }

  [data-slot="button"][data-icon][data-size="normal"] {
    padding-left: 11px;
  }

  [data-slot="button"][data-icon][data-size="large"] {
    padding-left: 15px;
  }

  [data-slot="button"] :is([data-slot="icon-svg"], svg) {
    color: currentColor;
  }

  /* Neutral */
  [data-slot="button"][data-variant="neutral"] {
    background-color: var(--v2-background-bg-button-neutral);
    color: var(--v2-text-text-base);
    box-shadow: var(--v2-elevation-button-neutral);
  }

  [data-slot="button"][data-variant="neutral"]:is(:hover, [data-state="hover"]):not(:disabled) {
    background-image:
      linear-gradient(90deg, var(--v2-overlay-simple-overlay-hover) 0%, var(--v2-overlay-simple-overlay-hover) 100%),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="button"][data-variant="neutral"]:is(:active, [data-state="pressed"], [data-expanded]):not(:disabled) {
    background-image:
      linear-gradient(
        90deg,
        var(--v2-overlay-simple-overlay-pressed) 0%,
        var(--v2-overlay-simple-overlay-pressed) 100%
      ),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="button"][data-variant="neutral"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Danger */
  [data-slot="button"][data-variant="danger"] {
    background-color: var(--v2-background-bg-button-neutral);
    color: var(--v2-state-fg-danger);
    box-shadow: var(--v2-elevation-button-neutral);
  }

  [data-slot="button"][data-variant="danger"]:is(:hover, [data-state="hover"]):not(:disabled) {
    background-image:
      linear-gradient(90deg, var(--v2-overlay-simple-overlay-hover) 0%, var(--v2-overlay-simple-overlay-hover) 100%),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="button"][data-variant="danger"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-image:
      linear-gradient(
        90deg,
        var(--v2-overlay-simple-overlay-pressed) 0%,
        var(--v2-overlay-simple-overlay-pressed) 100%
      ),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="button"][data-variant="danger"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Warning */
  [data-slot="button"][data-variant="warning"] {
    background-color: var(--v2-background-bg-button-neutral);
    color: var(--v2-state-fg-warning);
    box-shadow: var(--v2-elevation-button-neutral);
  }

  [data-slot="button"][data-variant="warning"]:is(:hover, [data-state="hover"]):not(:disabled) {
    background-image:
      linear-gradient(90deg, var(--v2-overlay-simple-overlay-hover) 0%, var(--v2-overlay-simple-overlay-hover) 100%),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="button"][data-variant="warning"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-image:
      linear-gradient(
        90deg,
        var(--v2-overlay-simple-overlay-pressed) 0%,
        var(--v2-overlay-simple-overlay-pressed) 100%
      ),
      linear-gradient(90deg, var(--v2-background-bg-button-neutral) 0%, var(--v2-background-bg-button-neutral) 100%);
  }

  [data-slot="button"][data-variant="warning"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Outline */
  [data-slot="button"][data-variant="outline"] {
    background-color: transparent;
    color: var(--v2-text-text-base);
    box-shadow: inset 0 0 0 1px var(--v2-border-border-muted);
  }

  [data-slot="button"][data-variant="outline"]:is(:hover, [data-state="hover"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="button"][data-variant="outline"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="outline"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Contrast */
  [data-slot="button"][data-variant="contrast"] {
    background-image:
      linear-gradient(180deg, var(--v2-alpha-light-20) 0%, var(--v2-alpha-light-0) 100%),
      linear-gradient(90deg, var(--v2-background-bg-contrast) 0%, var(--v2-background-bg-contrast) 100%);
    color: var(--v2-text-text-contrast);
    text-shadow: 0 0.5px 0.5px rgba(0, 0, 0, 0.3);
    box-shadow: var(--v2-elevation-button-contrast);
  }

  [data-slot="button"][data-variant="contrast"]:is(:hover, [data-state="hover"]):not(:disabled) {
    background-image:
      linear-gradient(
        90deg,
        var(--v2-overlay-simple-overlay-contrast-hover) 0%,
        var(--v2-overlay-simple-overlay-contrast-hover) 100%
      ),
      linear-gradient(180deg, var(--v2-alpha-light-20) 0%, var(--v2-alpha-light-0) 100%),
      linear-gradient(90deg, var(--v2-background-bg-contrast) 0%, var(--v2-background-bg-contrast) 100%);
  }

  [data-slot="button"][data-variant="contrast"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-image:
      linear-gradient(
        90deg,
        var(--v2-overlay-simple-overlay-contrast-pressed) 0%,
        var(--v2-overlay-simple-overlay-contrast-pressed) 100%
      ),
      linear-gradient(180deg, var(--v2-alpha-light-20) 0%, var(--v2-alpha-light-0) 100%),
      linear-gradient(90deg, var(--v2-background-bg-contrast) 0%, var(--v2-background-bg-contrast) 100%);
  }

  [data-slot="button"][data-variant="contrast"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.4;
    cursor: not-allowed;
  }

  /* Loading */
  [data-slot="button"][data-variant="loading"] {
    background: var(--v2-background-bg-layer-02);
    color: var(--v2-text-text-base);
    box-shadow: inset 0 0 0 0.5px var(--v2-border-border-muted);
    cursor: default;
    pointer-events: none;
  }

  /* Ghost */
  [data-slot="button"][data-variant="ghost"] {
    background-color: transparent;
    color: var(--v2-text-text-base);
  }

  [data-slot="button"][data-variant="ghost"]:is(:hover, [data-state="hover"]):not(:disabled):not([data-expanded]) {
    background-color: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="button"][data-variant="ghost"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="ghost"]:where([data-expanded]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="ghost"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Ghost muted */
  [data-slot="button"][data-variant="ghost-muted"] {
    background-color: transparent;
    color: var(--v2-text-text-muted);
    font-weight: 440;
  }

  [data-slot="button"][data-variant="ghost-muted"] :is([data-slot="icon-svg"], svg) {
    color: var(--v2-icon-icon-muted);
  }

  @media (hover: hover) {
    [data-slot="button"][data-variant="ghost-muted"]:is(:hover, [data-state="hover"]):not(:disabled):not(
        [data-expanded]
      ) {
      background-color: var(--v2-overlay-simple-overlay-hover);
    }
  }

  [data-slot="button"][data-variant="ghost-muted"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="ghost-muted"]:where([data-expanded]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
    color: var(--v2-text-text-base);
  }

  [data-slot="button"][data-variant="ghost-muted"]:where([data-expanded]):not(:disabled)
    :is([data-slot="icon-svg"], svg) {
    color: var(--v2-icon-icon-base);
  }

  [data-slot="button"][data-variant="ghost-muted"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Ghost danger: a destructive action that sits beside other ghost buttons */
  [data-slot="button"][data-variant="ghost-danger"] {
    background-color: transparent;
    color: var(--v2-state-fg-danger);
  }

  [data-slot="button"][data-variant="ghost-danger"]:is(:hover, [data-state="hover"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="button"][data-variant="ghost-danger"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="ghost-danger"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Ghost faint */
  [data-slot="button"][data-variant="ghost-faint"] {
    background-color: transparent;
    color: var(--v2-text-text-faint);
  }

  [data-slot="button"][data-variant="ghost-faint"] :is([data-slot="icon-svg"], svg) {
    color: var(--v2-icon-icon-faint);
  }

  [data-slot="button"][data-variant="ghost-faint"]:is(:hover, [data-state="hover"]):not(:disabled):not(
      [data-expanded]
    ) {
    background-color: var(--v2-overlay-simple-overlay-hover);
  }

  [data-slot="button"][data-variant="ghost-faint"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="ghost-faint"]:where([data-expanded]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="ghost-faint"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* Submit: the composer's main action. Shares the brighter contrast icon-button styling. */
  [data-slot="button"][data-variant="submit"] {
    --submit-highlight: var(--v2-alpha-light-20);
    --submit-hover: var(--v2-overlay-simple-overlay-contrast-hover);

    background-image:
      linear-gradient(180deg, var(--submit-highlight) 0%, var(--v2-alpha-light-0) 100%),
      linear-gradient(
        90deg,
        var(--v2-background-bg-icon-button-contrast) 0%,
        var(--v2-background-bg-icon-button-contrast) 100%
      );
    color: var(--v2-text-text-contrast);
    text-shadow: 0 0.5px 0.5px rgba(0, 0, 0, 0.3);
    box-shadow: var(--v2-elevation-button-contrast);
  }

  [data-color-scheme="dark"] [data-slot="button"][data-variant="submit"] {
    --submit-highlight: var(--v2-alpha-light-60);
    --submit-hover: var(--v2-alpha-dark-8);

    color: var(--v2-text-text-inverse);
  }

  @media (hover: hover) {
    [data-slot="button"][data-variant="submit"]:is(:hover, [data-state="hover"]):not(:disabled) {
      background-image:
        linear-gradient(90deg, var(--submit-hover) 0%, var(--submit-hover) 100%),
        linear-gradient(180deg, var(--submit-highlight) 0%, var(--v2-alpha-light-0) 100%),
        linear-gradient(
          90deg,
          var(--v2-background-bg-icon-button-contrast) 0%,
          var(--v2-background-bg-icon-button-contrast) 100%
        );
    }
  }

  [data-slot="button"][data-variant="submit"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-image:
      linear-gradient(
        90deg,
        var(--v2-overlay-simple-overlay-contrast-pressed) 0%,
        var(--v2-overlay-simple-overlay-contrast-pressed) 100%
      ),
      linear-gradient(180deg, var(--submit-highlight) 0%, var(--v2-alpha-light-0) 100%),
      linear-gradient(
        90deg,
        var(--v2-background-bg-icon-button-contrast) 0%,
        var(--v2-background-bg-icon-button-contrast) 100%
      );
  }

  [data-slot="button"][data-variant="submit"]:is(:disabled, [data-disabled], [data-state="disabled"]) {
    opacity: 0.4;
    cursor: not-allowed;
  }

  /*
   * Kitsaas addition: the settings-sidebar link (`variant="nav"`). Measured
   * from opencode's app shell; not part of button-v2.
   */
  [data-slot="button"][data-variant="nav"] {
    height: 28px;
    flex-shrink: 0;
    justify-content: flex-start;
    gap: 8px;
    padding: 0 6px;
    border-radius: 6px;
    font-weight: 440;
    color: var(--v2-text-text-muted);
  }

  [data-slot="button"][data-variant="nav"] :is([data-slot="icon-svg"], svg) {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    color: var(--v2-icon-icon-muted);
  }

  @media (hover: hover) {
    [data-slot="button"][data-variant="nav"]:is(:hover, [data-state="hover"]):not([data-active]):not(:disabled) {
      background-color: var(--v2-overlay-simple-overlay-hover);
      color: var(--v2-text-text-base);
    }

    [data-slot="button"][data-variant="nav"]:is(:hover, [data-state="hover"]):not([data-active]):not(:disabled)
      :is([data-slot="icon-svg"], svg) {
      color: var(--v2-icon-icon-base);
    }
  }

  [data-slot="button"][data-variant="nav"]:is(:active, [data-state="pressed"]):not(:disabled) {
    background-color: var(--v2-overlay-simple-overlay-pressed);
  }

  [data-slot="button"][data-variant="nav"][data-active] {
    background-color: var(--v2-background-bg-layer-03);
    color: var(--v2-text-text-base);
  }

  [data-slot="button"][data-variant="nav"][data-active] :is([data-slot="icon-svg"], svg) {
    color: var(--v2-icon-icon-base);
  }

  /* ui-sdk keeps a Promise-returning onClick pending; presses do nothing until it settles. */
  [data-slot="button"][data-pending] {
    cursor: default;
    pointer-events: none;
  }
}
